sys_script_include.script:
var IAW_Helper = Class.create();
IAW_Helper.prototype = {
    initialize: function() {
        var env = gs.getProperty('x_hsb11_iaw_widget.mss_iaw_url');
        var token = gs.getProperty('x_hsb11_iaw_widget.hsbcmss_iaw_api_token');
        var response;

        this.env = env;
        this.token = token;

    },
    // Function to send update fund code request
    cuh_send: function(task_id, ctac_trade_id, counterparty_code, ctac_allocation_id, subaccount_view) {

        var sr = new sn_ws.RESTMessageV2("IAW Outbound API", "CTAC Update Handler");
        sr.setStringParameterNoEscape("iaw_api_token", this.token);
        sr.setStringParameterNoEscape("base_api_uri", this.env);
        sr.setStringParameterNoEscape("cuh_endpoint", gs.getProperty('x_hsb11_iaw_widget.mss_iaw_cuh_endpoint'));
        sr.setStringParameterNoEscape("sys_id", task_id);
        sr.setStringParameterNoEscape("ctac_trade_id", ctac_trade_id);
        sr.setStringParameterNoEscape("counterparty_code", counterparty_code);
        sr.setStringParameterNoEscape("ctac_allocation_id", ctac_allocation_id);
        sr.setStringParameterNoEscape("subaccount_view", subaccount_view);
        response = sr.executeAsync();
        return response;
    },
    //
    fcih_send: function(task_id, ctac_trade_id, counterparty_code, ctac_trans_msg_p1, counterparty_account) {

        var sr = new sn_ws.RESTMessageV2("IAW Outbound API", "Fund Code Identification Handler");
        sr.setStringParameterNoEscape("iaw_api_token", this.token);
        sr.setStringParameterNoEscape("base_api_uri", this.env);
        sr.setStringParameterNoEscape("fcih_endpoint", gs.getProperty('x_hsb11_iaw_widget.mss_iaw_fcih_endpoint'));
        sr.setStringParameterNoEscape("sys_id", task_id);
        sr.setStringParameterNoEscape("ctac_trade_id", ctac_trade_id);
        sr.setStringParameterNoEscape("counterparty_code", counterparty_code);
        sr.setStringParameterNoEscape("ctac_trans_msg_p1", ctac_trans_msg_p1);
        sr.setStringParameterNoEscape("counterparty_account", counterparty_account);
        response = sr.executeAsync();
        return response;
    },

    almh_send: function(task_id, ctac_trade_id, counterparty_code, ctac_allocation_id, trading_entity_id, buy_sell, exchange_id, ctac_ctm_trade_detail_fld_comp) {

        var sr = new sn_ws.RESTMessageV2("IAW Outbound API", "Allocation Mismatch Handler");
        sr.setStringParameterNoEscape("iaw_api_token", this.token);
        sr.setStringParameterNoEscape("base_api_uri", this.env);
        sr.setStringParameterNoEscape("almh_endpoint", gs.getProperty('x_hsb11_iaw_widget.mss_iaw_almh_endpoint'));
        sr.setStringParameterNoEscape("sys_id", task_id);
        sr.setStringParameterNoEscape("ctac_trade_id", ctac_trade_id);
        sr.setStringParameterNoEscape("counterparty_code", counterparty_code);
        sr.setStringParameterNoEscape("ctac_allocation_id", ctac_allocation_id);
        sr.setStringParameterNoEscape("trading_entity_id", trading_entity_id);
        sr.setStringParameterNoEscape("buy_sell", buy_sell);
        sr.setStringParameterNoEscape("exchange_id", exchange_id);
        sr.setStringParameterNoEscape("ctac_ctm_trade_detail_fld_comp", ctac_ctm_trade_detail_fld_comp);
        response = sr.executeAsync();
        return response;
    },

    btmh_send: function(task_id, ctac_trade_id, counterparty_code, trading_entity_id, buy_sell, exchange_id, ctac_ctm_trade_level_fld_comp) {

        var sr = new sn_ws.RESTMessageV2("IAW Outbound API", "Block Trade Mismatch Handler");
        sr.setStringParameterNoEscape("iaw_api_token", this.token);
        sr.setStringParameterNoEscape("base_api_uri", this.env);
        sr.setStringParameterNoEscape("btmh_endpoint", gs.getProperty('x_hsb11_iaw_widget.mss_iaw_btmh_endpoint'));
        sr.setStringParameterNoEscape("sys_id", task_id);
        sr.setStringParameterNoEscape("ctac_trade_id", ctac_trade_id);
        sr.setStringParameterNoEscape("counterparty_code", counterparty_code);
        sr.setStringParameterNoEscape("trading_entity_id", trading_entity_id);
        sr.setStringParameterNoEscape("buy_sell", buy_sell);
        sr.setStringParameterNoEscape("exchange_id", exchange_id);
        sr.setStringParameterNoEscape("ctac_ctm_trade_level_fld_comp", ctac_ctm_trade_level_fld_comp);
        response = sr.executeAsync();
        return response;
    },

    maih_send: function(task_id, block_trade_details, client_allocation_details) {

        var sr = new sn_ws.RESTMessageV2("IAW Outbound API", "Manual Allocation Instruction Handler");
        sr.setStringParameterNoEscape("iaw_api_token", this.token);
        sr.setStringParameterNoEscape("maih_endpoint", gs.getProperty('x_hsb11_iaw_widget.mss_iaw_maih_endpoint'));
        sr.setStringParameterNoEscape("base_api_uri", this.env);
        sr.setStringParameterNoEscape("sys_id", task_id);
        sr.setStringParameterNoEscape("block_trade_details", block_trade_details);
        sr.setStringParameterNoEscape("client_allocation_details", client_allocation_details);
        response = sr.executeAsync();
        return response;
    },



    type: 'IAW_Helper'
};
